# 🔹 Queue using Linked List
A **queue** follows **FIFO (First In, First Out)**. The first inserted element is the first one to be removed.

```cpp
#include <iostream>
using namespace std;

// Node structure for linked list
struct Node {
    int data;       // value stored
    Node* next;     // pointer to next node
};

// Class representing Queue
class Queue {
private:
    Node* front;  // points to first element
    Node* rear;   // points to last element

public:
    // Constructor to initialize empty queue
    Queue() {
        front = rear = nullptr;  // initially empty
    }

    // Function to insert (enqueue) element
    void enqueue(int value) {
        Node* newNode = new Node();
        newNode->data = value;
        newNode->next = nullptr;

        if (rear == nullptr) { // if queue is empty
            front = rear = newNode;
        } else {
            rear->next = newNode;  // link new node at end
            rear = newNode;        // update rear
        }
        cout << value << " enqueued into queue\n";
    }

    // Function to remove (dequeue) element
    void dequeue() {
        if (front == nullptr) { // empty queue
            cout << "Queue Underflow! Cannot dequeue.\n";
            return;
        }

        cout << front->data << " dequeued from queue\n";
        Node* temp = front;   // store front node
        front = front->next;  // move front
        if (front == nullptr) // if queue became empty
            rear = nullptr;
        delete temp;          // free memory
    }

    // Function to get front element
    void peek() {
        if (front == nullptr) {
            cout << "Queue is empty.\n";
            return;
        }
        cout << "Front element is: " << front->data << endl;
    }

    // Function to check if queue is empty
    bool isEmpty() {
        return front == nullptr;
    }
};
```

---

### 🔎 Explanation
- `Queue` has **two pointers**:  
  - `front` → points to first node (to remove).  
  - `rear` → points to last node (to add).  
- `enqueue()`:
  - Creates new node, adds at the end, updates `rear`.
  - If queue was empty, both `front` and `rear` point to new node.
- `dequeue()`:
  - Removes node at `front`, shifts it, deletes memory.
  - If queue becomes empty, also set `rear = nullptr`.
- `peek()` → shows front element.

---

# 🔹 Example Main Function

```cpp
int main() {
    // Stack demo
    Stack s;
    s.push(10);
    s.push(20);
    s.push(30);
    s.peek();
    s.pop();
    s.peek();

    cout << endl;

    // Queue demo
    Queue q;
    q.enqueue(100);
    q.enqueue(200);
    q.enqueue(300);
    q.peek();
    q.dequeue();
    q.peek();

    return 0;
}
```

